# Generated by build.py from recipe.yml for recipe surl-stand-up-mail-files-and-messages. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'shipped.eml'), "From: app@example.com`nTo: ann@example.com`nSubject: Order 7 shipped`n`nOrder 7 is on its way.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'invoice-7.txt'), "Invoice 7: 3 widgets, 42.00`n")
$server0 = Start-Process surl -ArgumentList '--allow-plaintext-auth', '--allow-uploads', '--mail-domain', 'example.com', '--mailbox', '"app@example.com:apppass;protocols=smtp,http,mqtt"', '--mailbox', 'ann@example.com:annpass', '--topic', '"orders/#;retain"', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/', 'http://127.0.0.1:8082/', 'mqtt://127.0.0.1:8083/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -T shipped.eml smtp://127.0.0.1:8080/example.com --next --digest -u app@example.com:apppass -T invoice-7.txt http://127.0.0.1:8082/invoice-7.txt --next -u app@example.com:apppass -d shipped mqtt://127.0.0.1:8083/orders/7
try { curl.exe -sS -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=HEADER.FIELDS%20(FROM%20TO%20SUBJECT)" --next --digest -u app@example.com:apppass http://127.0.0.1:8082/invoice-7.txt --next -u app@example.com:apppass -o event.bin mqtt://127.0.0.1:8083/orders/7 } finally { Stop-Process $server0 }
